      'DIRECTUS_LAUNCH_SELECTION_CHANGED','Review the current original operator source and workspace before starting.');
  const executed=await sourceIdentity(HERE);
  need(executed.sha256===selected.selection.sourceSha256,
    'DIRECTUS_LAUNCH_EXECUTION_CHANGED','The executed operator source differs from the reviewed source.');
